type TriageLevel = 'Level 1' | 'Level 2' | 'Level 3' | 'Level 4' | 'Level 5';
type Patient = {
  id: string; name: string; initials: string; age: number; sex: string; arrivalMethod: string;
  arrivalTime: string; waitMinutes: number; heartRate: number | null; bloodPressure: string;
  respiratoryRate: number | null; temperature: number | null; oxygenSaturation: number | null;
  consciousness: string; complaint: string; notes: string; painScore: number | null;
  riskFactors: string[]; triageLevel: TriageLevel; aiConfidence: number; textScore: number;
  vitalsScore: number; fusionScore: number; reasons: string[]; protectiveSignals: string[];
  missingInfo: string[]; reviewStatus: string; deteriorating: boolean; newlyArrived: boolean;
  history: { time: string; event: string; detail: string }[]; auditLog: { time: string; event: string; detail: string }[];
  clinicianLevel?: TriageLevel; overrideReason?: string;
};

const LEVELS: { value: TriageLevel; label: string; color: string; short: string }[] = [
  { value: 'Level 1', label: 'Immediate', color: '#d9554c', short: 'L1' },
  { value: 'Level 2', label: 'Emergent', color: '#df8a31', short: 'L2' },
  { value: 'Level 3', label: 'Urgent', color: '#c4a238', short: 'L3' },
  { value: 'Level 4', label: 'Less Urgent', color: '#39968a', short: 'L4' },
  { value: 'Level 5', label: 'Non-Urgent', color: '#5c7c99', short: 'L5' },
];
const levelMeta = (level: TriageLevel) => LEVELS.find((item) => item.value === level) ?? LEVELS[2];
const nowLabel = () => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

function scorePatient(input: Partial<Patient>): Pick<Patient, 'triageLevel' | 'aiConfidence' | 'textScore' | 'vitalsScore' | 'fusionScore' | 'reasons' | 'protectiveSignals' | 'missingInfo' | 'reviewStatus'> {
  const complaint = (input.complaint ?? '').toLowerCase();
  const risks = (input.riskFactors ?? []).join(' ').toLowerCase();
  const words = ['chest pain', 'stroke', 'unresponsive', 'severe bleeding', 'difficulty breathing', 'seizure', 'anaphylaxis'];
  const urgentWords = ['shortness', 'breath', 'abdominal pain', 'fracture', 'fever', 'confusion', 'syncope', 'head injury'];
  const danger = words.some((word) => complaint.includes(word));
  const urgent = urgentWords.some((word) => complaint.includes(word));
  const reasons: string[] = [];
  const protective: string[] = [];
  const missing: string[] = [];
  let text = danger ? 92 : urgent ? 66 : 34;
  let vitals = 30;
  const hr = input.heartRate ?? null;
  const rr = input.respiratoryRate ?? null;
  const spo2 = input.oxygenSaturation ?? null;
  const temp = input.temperature ?? null;
  if (input.consciousness && input.consciousness !== 'Alert') { text += 12; reasons.push('Altered consciousness documented'); }
  else protective.push('Alert on arrival');
  if (hr !== null && (hr > 120 || hr < 45)) { vitals += 30; reasons.push(`Heart rate ${hr} bpm outside expected range`); }
  if (rr !== null && rr > 24) { vitals += 24; reasons.push(`Respiratory rate ${rr}/min elevated`); }
  if (spo2 !== null && spo2 < 94) { vitals += 34; reasons.push(`Oxygen saturation ${spo2}% below threshold`); }
  if (temp !== null && (temp > 39 || temp < 35)) { vitals += 15; reasons.push(`Temperature ${temp}°C flagged`); }
  if (input.bloodPressure && /[0-8]\d\/|1[6-9]\d\/|\/1[1-9]\d/.test(input.bloodPressure)) { vitals += 14; reasons.push('Blood pressure needs clinician review'); }
  if (risks.includes('pregnan') || risks.includes('anticoag') || risks.includes('immun')) { text += 14; reasons.push('Risk factor increases acuity signal'); }
  if ((input.age ?? 40) < 2 || (input.age ?? 40) > 75) { text += 8; reasons.push('Age band adds uncertainty'); }
  if (!input.heartRate) missing.push('Heart rate');
  if (!input.bloodPressure) missing.push('Blood pressure');
  if (!input.oxygenSaturation) missing.push('Oxygen saturation');
  if (!input.consciousness) missing.push('Consciousness');
  if (!input.complaint?.trim()) missing.push('Chief complaint');
  const penalty = Math.min(missing.length * 8, 24);
  const fusion = Math.min(99, Math.round((text * .48 + Math.min(100, vitals) * .52) - penalty));
  if (missing.length) reasons.push(`${missing.length} required signal${missing.length > 1 ? 's' : ''} missing`);
  if (!reasons.length) reasons.push('Stable initial signal profile');
  const level: TriageLevel = fusion >= 83 ? 'Level 1' : fusion >= 68 ? 'Level 2' : fusion >= 49 ? 'Level 3' : fusion >= 29 ? 'Level 4' : 'Level 5';
  const confidence = Math.max(54, Math.min(98, 96 - missing.length * 9 - (input.notes?.length ? 0 : 4)));
  return { triageLevel: level, aiConfidence: confidence, textScore: Math.min(text, 99), vitalsScore: Math.min(vitals, 99), fusionScore: fusion, reasons, protectiveSignals: protective, missingInfo: missing, reviewStatus: missing.length > 1 ? 'Needs clinician review' : 'Pending review' };
}

