function loadPatients(): Patient[] {
  try { const saved = localStorage.getItem('patient-triage-patients'); return saved ? JSON.parse(saved) : seedPatients; } catch { return seedPatients; }
}
function savePatients(patients: Patient[]) { localStorage.setItem('patient-triage-patients', JSON.stringify(patients)); }

function Tip({ children, text }: { children: ReactNode; text: string }) {
  return <span className="group relative inline-flex items-center">{children}<span className="pointer-events-none absolute bottom-full left-1/2 z-30 mb-2 hidden w-56 -translate-x-1/2 border border-[hsl(var(--border))] bg-[hsl(var(--sidebar))] p-2 text-[11px] leading-snug text-[hsl(var(--sidebar-foreground))] shadow-md group-hover:block">{text}</span></span>;
}
function LevelBadge({ level, compact = false }: { level: TriageLevel; compact?: boolean }) {
  const meta = levelMeta(level);
  return <span data-testid={`status-triage-${level}`} className="inline-flex items-center gap-1.5 border px-2 py-1 text-[10px] font-bold uppercase tracking-wide" style={{ borderColor: `${meta.color}66`, color: meta.color, backgroundColor: `${meta.color}12` }}><span className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: meta.color }} />{compact ? meta.short : `${meta.short} · ${meta.label}`}</span>;
}
function Button({ children, onClick, variant = 'primary', className = '', disabled = false, type = 'button', testId }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; disabled?: boolean; type?: 'button' | 'submit'; testId?: string }) {
  const variants = { primary: 'bg-[hsl(var(--primary))] text-white hover:brightness-110', secondary: 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] hover:bg-[hsl(var(--secondary))]', ghost: 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--secondary))] hover:text-[hsl(var(--foreground))]', danger: 'border border-[hsl(var(--destructive)/.35)] bg-[hsl(var(--destructive)/.08)] text-[hsl(var(--destructive))] hover:bg-[hsl(var(--destructive)/.14)]' };
  return <button type={type} data-testid={testId} disabled={disabled} onClick={onClick} className={`inline-flex min-h-9 items-center justify-center gap-2 px-3 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-45 ${variants[variant]} ${className}`}>{children}</button>;
}
function SectionHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-6 flex items-end justify-between gap-4"><div><div className="eyebrow mb-2 text-[hsl(var(--primary))]">{eyebrow}</div><h2 className="text-2xl font-bold tracking-tight">{title}</h2>{detail && <p className="mt-1 max-w-2xl text-sm text-[hsl(var(--muted-foreground))]">{detail}</p>}</div>{action}</div>;
}

